class Solution {
    struct Edge { int to, rev; long long cap, cost; };
    vector<vector<Edge>> g;
    void addEdge(int u,int v,long long cap,long long cost) {
        Edge a={v,(int)g[v].size(),cap,cost};
        Edge b={u,(int)g[u].size(),0,-cost};
        g[u].push_back(a);g[v].push_back(b);
    }
public:
    long long minMoves(vector<int>& balance) {
        int n=balance.size(),S=n,T=n+1;
        long long total=0,need=0;
        for(int x:balance)total+=x;
        if(total<0)return -1;
        g.assign(n+2,{});
        const long long INF=(1LL<<60);
        for(int i=0;i<n;++i) {
            if(balance[i]>0)addEdge(S,i,balance[i],0);
            if(balance[i]<0) {
                addEdge(i,T,-(long long)balance[i],0);
                need-=balance[i];
            }
            if(n>1) addEdge(i,(i+1)%n,INF,1);
            if(n>1) addEdge(i,(i+n-1)%n,INF,1);
        }
        vector<long long> pot(n+2,0),dist(n+2);
        long long answer=0;
        while(need>0) {
            fill(dist.begin(),dist.end(),INF);
            vector<int> pv(n+2,-1),pe(n+2,-1);
            priority_queue<pair<long long,int>,vector<pair<long long,int>>,
                           greater<pair<long long,int>>> pq;
            dist[S]=0;pq.push({0,S});
            while(!pq.empty()) {
                auto cur=pq.top();pq.pop();
                long long d=cur.first;int u=cur.second;
                if(d!=dist[u])continue;
                for(int i=0;i<(int)g[u].size();++i) {
                    Edge &e=g[u][i];
                    if(e.cap==0)continue;
                    long long nd=d+e.cost+pot[u]-pot[e.to];
                    if(nd<dist[e.to]) {
                        dist[e.to]=nd;pv[e.to]=u;pe[e.to]=i;
                        pq.push({nd,e.to});
                    }
                }
            }
            if(dist[T]==INF)return -1;
            for(int v=0;v<n+2;++v)if(dist[v]<INF)pot[v]+=dist[v];
            long long f=need;
            for(int v=T;v!=S;v=pv[v])
                f=min(f,g[pv[v]][pe[v]].cap);
            for(int v=T;v!=S;v=pv[v]) {
                Edge &e=g[pv[v]][pe[v]];
                e.cap-=f;g[v][e.rev].cap+=f;
                answer+=f*e.cost;
            }
            need-=f;
        }
        return answer;
    }
};
